"""loyalty-get: GET /loyalty/{customer_id}

Authorization first (owner of the path id, or Admin per UserGroupsTable);
nothing is read from the loyalty table when it fails. The total is the sum
over one page of a Scan filtered on customerId + flag='active', so a
storage failure counts as 0 and the tier maths below still answers 200
(SI-12, SI-13). Tier thresholds and the remaining-points maths are the
monolith's constants. Every response carries the app-wide headers (SI-14).
"""
import json
import os
from decimal import Decimal

import boto3
from boto3.dynamodb.conditions import Attr

LOYALTY_TABLE_NAME = os.environ["LOYALTY_TABLE_NAME"]
USER_GROUPS_TABLE_NAME = os.environ["USER_GROUPS_TABLE_NAME"]

_dynamodb = boto3.resource("dynamodb")
loyalty_table = _dynamodb.Table(LOYALTY_TABLE_NAME)
user_groups_table = _dynamodb.Table(USER_GROUPS_TABLE_NAME)

TIER_GOLD = 100000
TIER_SILVER = 50000


def json_response(status_code, payload):
    """Single place where the app-wide response headers are set (SI-14)."""
    return {
        "statusCode": status_code,
        "headers": {
            "Content-Type": "application/json",
            "Access-Control-Allow-Origin": "*",
        },
        "body": json.dumps(payload),
    }


def claims_of(event):
    """Identity comes from the gateway-verified claims only (SI-10)."""
    return (event.get("requestContext") or {}).get("authorizer", {}).get("claims") or {}


def is_admin(sub):
    """Admin membership is read from UserGroupsTable on every request; no row
    (or a failed read) means no groups, never a 401 (SI-10)."""
    try:
        response = user_groups_table.get_item(Key={"sub": sub})
    except Exception as exc:  # noqa: BLE001
        print(f"Error getting user groups {sub}: {str(exc)}")
        return False
    item = response.get("Item") or {}
    groups = item.get("groups") or []
    return "Admin" in list(groups)


def get_loyalty_points(customer_id):
    """Sum of the first Scan page's active points; a failure counts as 0."""
    try:
        response = loyalty_table.scan(
            FilterExpression=Attr("customerId").eq(customer_id) & Attr("flag").eq("active")
        )
        total = 0
        for item in response.get("Items", []):
            total += int(item.get("points", 0))
        return total
    except Exception as exc:  # noqa: BLE001
        print(f"Error getting loyalty points for {customer_id}: {str(exc)}")
        return 0


def get_loyalty_level(points):
    if points >= TIER_GOLD:
        return "gold"
    if points >= TIER_SILVER:
        return "silver"
    return "bronze"


def get_remaining_points_to_next_tier(points, level):
    if level == "bronze":
        return TIER_SILVER - points
    if level == "silver":
        return TIER_GOLD - points
    return 0


def lambda_handler(event, context):
    customer_id = (event.get("pathParameters") or {}).get("customer_id")
    sub = claims_of(event).get("sub")

    if sub != customer_id and not is_admin(sub):
        return json_response(403, {"error": "Access denied. You can only access your own resources."})

    total_points = get_loyalty_points(customer_id)
    level = get_loyalty_level(total_points)
    remaining_points = get_remaining_points_to_next_tier(total_points, level)

    return json_response(200, {
        "points": total_points,
        "level": level,
        "remainingPoints": remaining_points,
    })
