=====flights-reserve=====
"""flights-reserve: POST /flights/{flight_id}/reserve

One atomic conditional decrement - never a read-then-write, the condition
is what prevents overselling (business_rules[2]). "Does not exist" and
"fully booked" share one answer; any other DynamoDB failure is wrapped
into a ValueError, so this endpoint never answers 5xx (SI-13).
Every response carries the app-wide headers (SI-14).
"""
import json
import os

import boto3

FLIGHT_TABLE_NAME = os.environ["FLIGHT_TABLE_NAME"]

_dynamodb = boto3.resource("dynamodb")
flight_table = _dynamodb.Table(FLIGHT_TABLE_NAME)
CONDITIONAL_CHECK_FAILED = _dynamodb.meta.client.exceptions.ConditionalCheckFailedException


def json_response(status_code, payload):
    """Single place where the app-wide response headers are set (SI-14)."""
    return {
        "statusCode": status_code,
        "headers": {
            "Content-Type": "application/json",
            "Access-Control-Allow-Origin": "*",
        },
        "body": json.dumps(payload),
    }


def reserve_flight_seat(flight_id):
    """seatCapacity = seatCapacity - 1 when a seat is actually left."""
    try:
        flight_table.update_item(
            Key={"id": flight_id},
            UpdateExpression="SET seatCapacity = seatCapacity - :dec",
            ConditionExpression="seatCapacity > :zero AND attribute_exists(id)",
            ExpressionAttributeValues={":dec": 1, ":zero": 0},
            ReturnValues="UPDATED_NEW",
        )
        return True
    except CONDITIONAL_CHECK_FAILED:
        raise ValueError(f"Flight {flight_id} is fully booked or does not exist")
    except Exception as exc:  # noqa: BLE001 - never a 5xx on this endpoint
        raise ValueError(f"Failed to reserve seat: {str(exc)}")


def lambda_handler(event, context):
    try:
        flight_id = (event.get("pathParameters") or {}).get("flight_id")
        reserve_flight_seat(flight_id)
        return json_response(200, {"status": "SUCCESS"})
    except ValueError as exc:
        return json_response(400, {"error": str(exc), "type": "ValueError"})
    except Exception as exc:  # noqa: BLE001 - same mapping as the monolith
        return json_response(500, {"error": str(exc), "type": type(exc).__name__})
=====flights-release=====
"""flights-release: POST /flights/{flight_id}/release

Conditional increment of seatCapacity, capped by the maximumSeating stored
on that very flight item (business_rules[2]). Two different 400 texts are
the contract: a missing flight comes back with the 'Failed to release
seat: ' prefix (the monolith's inner ValueError is re-wrapped by the same
function), while "already at maximum capacity" (condition failure) has no
prefix. No requester is tracked, so repeated releases climb to the cap
(business_rules[5]). Every response carries the app-wide headers (SI-14).
"""
import json
import os
from decimal import Decimal

import boto3

FLIGHT_TABLE_NAME = os.environ["FLIGHT_TABLE_NAME"]

_dynamodb = boto3.resource("dynamodb")
flight_table = _dynamodb.Table(FLIGHT_TABLE_NAME)
CONDITIONAL_CHECK_FAILED = _dynamodb.meta.client.exceptions.ConditionalCheckFailedException


def json_response(status_code, payload):
    """Single place where the app-wide response headers are set (SI-14)."""
    return {
        "statusCode": status_code,
        "headers": {
            "Content-Type": "application/json",
            "Access-Control-Allow-Origin": "*",
        },
        "body": json.dumps(payload),
    }


def from_dynamodb(value):
    """Decimal -> int when whole, float otherwise (SI-16)."""
    if isinstance(value, Decimal):
        if value % 1 == 0:
            return int(value)
        return float(value)
    if isinstance(value, dict):
        return {k: from_dynamodb(v) for k, v in value.items()}
    if isinstance(value, list):
        return [from_dynamodb(v) for v in value]
    return value


def get_flight(flight_id):
    """A read failure is swallowed into None, like the monolith's storage."""
    try:
        response = flight_table.get_item(Key={"id": flight_id})
    except Exception as exc:  # noqa: BLE001
        print(f"Error getting flight {flight_id}: {str(exc)}")
        return None
    if "Item" in response:
        return from_dynamodb(response["Item"])
    return None


def release_flight_seat(flight_id):
    try:
        flight = get_flight(flight_id)
        if not flight:
            raise ValueError(f"Flight {flight_id} does not exist")

        flight_table.update_item(
            Key={"id": flight_id},
            UpdateExpression="SET seatCapacity = seatCapacity + :inc",
            ConditionExpression="seatCapacity < :max",
            ExpressionAttributeValues={":inc": 1, ":max": flight["maximumSeating"]},
            ReturnValues="UPDATED_NEW",
        )
        return True
    except CONDITIONAL_CHECK_FAILED:
        raise ValueError("Cannot release seat, already at maximum capacity")
    except Exception as exc:  # noqa: BLE001 - includes the "does not exist" above
        raise ValueError(f"Failed to release seat: {str(exc)}")


def lambda_handler(event, context):
    try:
        flight_id = (event.get("pathParameters") or {}).get("flight_id")
        release_flight_seat(flight_id)
        return json_response(200, {"status": "SUCCESS"})
    except ValueError as exc:
        return json_response(400, {"error": str(exc), "type": "ValueError"})
    except Exception as exc:  # noqa: BLE001 - same mapping as the monolith
        return json_response(500, {"error": str(exc), "type": type(exc).__name__})
